"""Pilot-only GBM route: screen + HistGradientBoostingClassifier.

Every choice here (screen, grid, folds) is fixed before any held-out data is scored;
all fitting happens on data/pilot.csv only.
"""
import numpy as np
from sklearn.ensemble import HistGradientBoostingClassifier
from sklearn.metrics import roc_auc_score
from sklearn.model_selection import StratifiedKFold

GBM_GRID = [
    {"learning_rate": lr, "max_leaf_nodes": leaves, "min_samples_leaf": msl,
     "l2_regularization": l2}
    for lr in (0.03, 0.1)
    for leaves in (3, 7, 15)
    for msl in (10, 20)
    for l2 in (0.0, 1.0)
]


def make_gbm(p):
    return HistGradientBoostingClassifier(
        max_iter=200, early_stopping=False, random_state=0, **p)


def nested_gb_cv(X, y, screen_fn, grid=None, n_out=5, n_in=4, seed=0):
    """Honest nested CV: the screen and the grid choice are made inside every outer fold.

    Returns per-outer-fold AUCs, the inner-selected params, and per-fold feature counts.
    """
    if grid is None:
        grid = GBM_GRID
    skf = StratifiedKFold(n_out, shuffle=True, random_state=seed)
    outer, chosen, n_feats = [], [], []
    for tr, te in skf.split(X, y):
        feats = screen_fn(X[tr], y[tr])
        Xu, yu = X[tr][:, feats], y[tr]
        inner = StratifiedKFold(n_in, shuffle=True, random_state=seed)
        best_score, best_p = -1.0, None
        for p in grid:
            aucs = []
            for itr, ite in inner.split(Xu, yu):
                m = make_gbm(p).fit(Xu[itr], yu[itr])
                aucs.append(roc_auc_score(yu[ite], m.predict_proba(Xu[ite])[:, 1]))
            score = float(np.mean(aucs))
            if score > best_score:
                best_score, best_p = score, p
        m = make_gbm(best_p).fit(Xu, yu)
        outer.append(roc_auc_score(y[te], m.predict_proba(X[te][:, feats])[:, 1]))
        chosen.append(best_p)
        n_feats.append(len(feats))
    return np.array(outer), chosen, n_feats
